/****************************************************************************
 * board/beken/chips/bk7258/sim_tests/test_yuv_buf.c
 *
 * Unit tests for bk7258_yuv_buf.c, compiled against the real production
 * source (unmodified).  Covers the whole-frame direct-capture
 * configuration: pixel/8 conversion, frame_blk calculation, the ctrl
 * field set, the interrupt enable/mask selection (frame events only, no
 * encode-path line-batch events), the frame-buffer install path
 * (em_base_addr/emr_base_addr), the global_ctrl reset-release sequence,
 * yuv_mode/h264_mode handling, YUV_ARV frame-done dispatch, error
 * accounting and write-1-to-clear interrupt acknowledgment.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <stdio.h>
#include <string.h>

#include "sim_stubs.h"
#include "bk7258_yuv_buf.h"
#include "irq.h"

static int g_failures;

#define CHECK(cond, ...) \
  do \
    { \
      if (!(cond)) \
        { \
          g_failures++; \
          printf("FAIL %s:%d: ", __func__, __LINE__); \
          printf(__VA_ARGS__); \
          printf("\n"); \
        } \
    } \
  while (0)

/* Mirrors bk7258_yuv_buf.c's private register layout as an independent
 * cross-check (see test_dma.c's header comment for the same rationale). */

#define TEST_YUV_BUF_BASE          0x48020000u
#define TEST_YUV_BUF_REG(word_off) (TEST_YUV_BUF_BASE + (word_off) * 4u)

#define TEST_YUV_BUF_GLOBAL_CTRL   TEST_YUV_BUF_REG(2)
#define TEST_YUV_BUF_GLOBAL_CTRL_SOFT_RESET      (1u << 0)
#define TEST_YUV_BUF_GLOBAL_CTRL_CLK_GATE_BYPASS (1u << 1)

#define TEST_YUV_BUF_CTRL          TEST_YUV_BUF_REG(4)
#define TEST_YUV_BUF_CTRL_YUV_MODE          (1u << 0)
#define TEST_YUV_BUF_CTRL_YUV_FMT_SEL_MASK  (0x3u << 2)
#define TEST_YUV_BUF_CTRL_HSYNC_REV         (1u << 6)
#define TEST_YUV_BUF_CTRL_VSYNC_REV         (1u << 7)
#define TEST_YUV_BUF_CTRL_SYNC_EDGE_DECT_EN (1u << 9)
#define TEST_YUV_BUF_CTRL_MCLK_DIV_MASK     (0x3u << 10)
#define TEST_YUV_BUF_CTRL_MCLK_DIV_SHIFT    10u
#define TEST_YUV_BUF_CTRL_H264_MODE         (1u << 12)
#define TEST_YUV_BUF_CTRL_SOI_HSYNC         (1u << 19)

#define TEST_YUV_BUF_PIXEL         TEST_YUV_BUF_REG(5)

#define TEST_YUV_BUF_EM_BASE_ADDR  TEST_YUV_BUF_REG(8)
#define TEST_YUV_BUF_INT_EN        TEST_YUV_BUF_REG(9)
#define TEST_YUV_BUF_INT_STATUS    TEST_YUV_BUF_REG(10)
#define TEST_YUV_BUF_INT_MASKS     TEST_YUV_BUF_REG(11)
#define TEST_YUV_BUF_EMR_BASE_ADDR TEST_YUV_BUF_REG(12)
#define TEST_YUV_BUF_RESIZE_PIXEL  TEST_YUV_BUF_REG(13)

#define TEST_INT_VSYNC_NEGE  (1u << 0)
#define TEST_INT_YUV_ARV     (1u << 1)
#define TEST_INT_SM0_WR      (1u << 2)
#define TEST_INT_SM1_WR      (1u << 3)
#define TEST_INT_SEN_FULL    (1u << 4)
#define TEST_INT_ENC_LINE    (1u << 5)
#define TEST_INT_SEN_RESL    (1u << 6)
#define TEST_INT_H264_ERR    (1u << 7)
#define TEST_INT_ENC_SLOW    (1u << 8)

/* A plausible PSRAM frame-buffer address (PSRAM is mapped at
 * 0x60000000): whole-frame capture points the hardware at the caller's
 * buffer rather than at a fixed line-buffer address. */

#define TEST_FRAME_BUF_ADDR  0x601901a0u

/****************************************************************************
 * configure(): geometry
 ****************************************************************************/

static void test_configure_640x480_pixel_register(void)
{
  uint32_t pixel_reg;
  uint32_t x_pixel;
  uint32_t y_pixel;
  uint32_t frame_blk;

  bk7258_sim_reset();

  /* 640/8=80, 480/8=60, frame_blk=(80*60)/2=2400, matching bk_dvp.c's
   * "yuv_mode_config.x_pixel = config->width / 8" convention. */

  bk7258_yuv_buf_configure(640, 480);

  pixel_reg = bk7258_sim_peek32(TEST_YUV_BUF_PIXEL);
  x_pixel = pixel_reg & 0xffu;
  y_pixel = (pixel_reg >> 8) & 0xffu;
  frame_blk = (pixel_reg >> 16) & 0xffffu;

  CHECK(x_pixel == 80u, "expected x_pixel = 640/8 = 80, got %u", x_pixel);
  CHECK(y_pixel == 60u, "expected y_pixel = 480/8 = 60, got %u", y_pixel);
  CHECK(frame_blk == 2400u,
        "expected frame_blk = (80*60)/2 = 2400, got %u", frame_blk);
}

static void test_configure_other_resolutions(void)
{
  uint32_t pixel_reg;

  bk7258_sim_reset();
  bk7258_yuv_buf_configure(864, 480);
  pixel_reg = bk7258_sim_peek32(TEST_YUV_BUF_PIXEL);
  CHECK((pixel_reg & 0xffu) == 108u,
        "expected x_pixel = 864/8 = 108 for 864x480, got %u",
        pixel_reg & 0xffu);
  CHECK(((pixel_reg >> 8) & 0xffu) == 60u,
        "expected y_pixel = 480/8 = 60 for 864x480, got %u",
        (pixel_reg >> 8) & 0xffu);

  bk7258_sim_reset();
  bk7258_yuv_buf_configure(1280, 720);
  pixel_reg = bk7258_sim_peek32(TEST_YUV_BUF_PIXEL);
  CHECK((pixel_reg & 0xffu) == 160u,
        "expected x_pixel = 1280/8 = 160 for 1280x720, got %u",
        pixel_reg & 0xffu);
  CHECK(((pixel_reg >> 8) & 0xffu) == 90u,
        "expected y_pixel = 720/8 = 90 for 1280x720, got %u",
        (pixel_reg >> 8) & 0xffu);
}

static void test_configure_resize_pixel_register(void)
{
  uint32_t resize;

  bk7258_sim_reset();
  bk7258_yuv_buf_configure(640, 480);

  /* resize_pixel: x at bit[1:8], y at bit[9:16]
   * (yuv_buf_hal_set_config_common() writes the same x_pixel/y_pixel
   * values as the pixel register). */

  resize = bk7258_sim_peek32(TEST_YUV_BUF_RESIZE_PIXEL);
  CHECK(((resize >> 1) & 0xffu) == 80u,
        "expected x_pixel_resize = 80, got %u", (resize >> 1) & 0xffu);
  CHECK(((resize >> 9) & 0xffu) == 60u,
        "expected y_pixel_resize = 60, got %u", (resize >> 9) & 0xffu);
}

/****************************************************************************
 * configure(): ctrl fields
 ****************************************************************************/

static void test_configure_ctrl_fields(void)
{
  uint32_t ctrl;

  bk7258_sim_reset();
  bk7258_yuv_buf_configure(640, 480);

  ctrl = bk7258_sim_peek32(TEST_YUV_BUF_CTRL);

  CHECK((ctrl & TEST_YUV_BUF_CTRL_SYNC_EDGE_DECT_EN) != 0,
        "expected sync_edge_dect_en set (yuv_buf_ll_enable_sync_edge_dect"
        "()), ctrl=0x%x", ctrl);
  CHECK(((ctrl & TEST_YUV_BUF_CTRL_MCLK_DIV_MASK) >>
         TEST_YUV_BUF_CTRL_MCLK_DIV_SHIFT) == 3u,
        "expected mclk_div = YUV_MCLK_DIV_3, ctrl=0x%x", ctrl);
  CHECK((ctrl & TEST_YUV_BUF_CTRL_SOI_HSYNC) != 0,
        "expected soi_hsync set (set_encode_begin_hsync_posedge()), "
        "ctrl=0x%x", ctrl);
  CHECK((ctrl & TEST_YUV_BUF_CTRL_YUV_FMT_SEL_MASK) == 0,
        "expected yuv_fmt_sel = YUYV (0) for GC2145, ctrl=0x%x", ctrl);
  CHECK((ctrl & (TEST_YUV_BUF_CTRL_HSYNC_REV |
                 TEST_YUV_BUF_CTRL_VSYNC_REV)) == 0,
        "expected hsync_rev/vsync_rev clear (GC2145 sync is active "
        "high), ctrl=0x%x", ctrl);
}

static void test_configure_clears_h264_mode(void)
{
  uint32_t ctrl;

  bk7258_sim_reset();
  bk7258_sim_poke32(TEST_YUV_BUF_CTRL, TEST_YUV_BUF_CTRL_H264_MODE);

  bk7258_yuv_buf_configure(640, 480);

  ctrl = bk7258_sim_peek32(TEST_YUV_BUF_CTRL);
  CHECK((ctrl & TEST_YUV_BUF_CTRL_H264_MODE) == 0,
        "expected configure() to clear a stale h264_mode bit, ctrl=0x%x",
        ctrl);
}

/****************************************************************************
 * configure(): interrupt selection
 ****************************************************************************/

static void test_configure_enables_frame_interrupts_only(void)
{
  uint32_t int_en;

  bk7258_sim_reset();
  bk7258_yuv_buf_configure(640, 480);

  int_en = bk7258_sim_peek32(TEST_YUV_BUF_INT_EN);

  CHECK((int_en & TEST_INT_YUV_ARV) != 0,
        "expected yuv_arv_int_en set (whole-frame done event), "
        "int_en=0x%x", int_en);
  CHECK((int_en & TEST_INT_VSYNC_NEGE) != 0,
        "expected vsync_nege_int_en set, int_en=0x%x", int_en);
  CHECK((int_en & (TEST_INT_SEN_FULL | TEST_INT_SEN_RESL |
                   TEST_INT_H264_ERR | TEST_INT_ENC_SLOW)) ==
        (TEST_INT_SEN_FULL | TEST_INT_SEN_RESL | TEST_INT_H264_ERR |
         TEST_INT_ENC_SLOW),
        "expected the four error interrupts enabled, int_en=0x%x", int_en);

  /* The encode-path line events must stay disabled: at 640x480@30fps
   * they would fire ~1800 times per second for a capture path that
   * does not use the line buffer at all. */

  CHECK((int_en & (TEST_INT_SM0_WR | TEST_INT_SM1_WR |
                   TEST_INT_ENC_LINE)) == 0,
        "expected sm0_wr/sm1_wr/enc_line interrupts to stay disabled "
        "for pure YUV whole-frame capture, int_en=0x%x", int_en);
}

static void test_configure_writes_error_masks(void)
{
  uint32_t masks;

  bk7258_sim_reset();
  bk7258_yuv_buf_configure(640, 480);

  /* yuv_buf_hal_set_err_mask(): vsync_nege 0, resl_err 1, sens_full 1,
   * enc_slow 1. */

  masks = bk7258_sim_peek32(TEST_YUV_BUF_INT_MASKS);
  CHECK(masks == ((1u << 2) | (1u << 3) | (1u << 4)),
        "expected int_masks = resl_err|sens_full|enc_slow = 0x1c, "
        "got 0x%x", masks);
}

static void test_configure_clears_stats(void)
{
  struct bk7258_yuv_buf_stats_s stats;

  bk7258_sim_reset();
  bk7258_yuv_buf_init();

  bk7258_sim_poke32(TEST_YUV_BUF_INT_STATUS, TEST_INT_YUV_ARV);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_YUVB);

  bk7258_yuv_buf_get_stats(&stats);
  CHECK(stats.isr_count == 1u, "expected 1 ISR counted, got %u",
        stats.isr_count);

  bk7258_yuv_buf_configure(640, 480);
  bk7258_yuv_buf_get_stats(&stats);

  CHECK(stats.isr_count == 0u && stats.frame_count == 0u &&
        stats.err_count == 0u,
        "expected configure() to reset the counters, got isr=%u frame=%u "
        "err=%u", stats.isr_count, stats.frame_count, stats.err_count);
}

/****************************************************************************
 * Frame buffer install
 ****************************************************************************/

static void test_set_frame_buffer_writes_em_and_emr(void)
{
  bk7258_sim_reset();
  bk7258_yuv_buf_configure(640, 480);

  bk7258_yuv_buf_set_frame_buffer(TEST_FRAME_BUF_ADDR);

  CHECK(bk7258_sim_peek32(TEST_YUV_BUF_EM_BASE_ADDR) ==
        TEST_FRAME_BUF_ADDR,
        "expected em_base_addr = the caller's frame buffer 0x%x, got "
        "0x%x", TEST_FRAME_BUF_ADDR,
        bk7258_sim_peek32(TEST_YUV_BUF_EM_BASE_ADDR));
  CHECK(bk7258_sim_peek32(TEST_YUV_BUF_EMR_BASE_ADDR) ==
        TEST_FRAME_BUF_ADDR,
        "expected emr_base_addr to match em_base_addr (whole-frame "
        "capture writes both, per bk_yuv_buf_set_em_base_addr()), got "
        "0x%x", bk7258_sim_peek32(TEST_YUV_BUF_EMR_BASE_ADDR));
  CHECK(bk7258_yuv_buf_get_frame_buffer() == TEST_FRAME_BUF_ADDR,
        "expected get_frame_buffer() to report the installed address, "
        "got 0x%x", bk7258_yuv_buf_get_frame_buffer());
}

static void test_set_frame_buffer_rearms_next_buffer(void)
{
  bk7258_sim_reset();
  bk7258_yuv_buf_configure(640, 480);

  bk7258_yuv_buf_set_frame_buffer(TEST_FRAME_BUF_ADDR);
  bk7258_yuv_buf_set_frame_buffer(TEST_FRAME_BUF_ADDR + 0x100000u);

  CHECK(bk7258_sim_peek32(TEST_YUV_BUF_EM_BASE_ADDR) ==
        TEST_FRAME_BUF_ADDR + 0x100000u,
        "expected a second set_frame_buffer() to re-point the hardware "
        "at the new buffer (this is how the V4L2 capture-done callback "
        "re-arms), got 0x%x",
        bk7258_sim_peek32(TEST_YUV_BUF_EM_BASE_ADDR));
}

/****************************************************************************
 * start()/stop()
 ****************************************************************************/

static void test_start_sets_yuv_mode_clears_h264_mode(void)
{
  uint32_t ctrl;

  bk7258_sim_reset();

  /* Pre-seed h264_mode set, to verify start() actively clears it (per
   * yuv_buf_hal_start_yuv_mode()) -- YUV direct-capture and H264 encode
   * are mutually exclusive hardware modes. */

  bk7258_sim_poke32(TEST_YUV_BUF_CTRL, TEST_YUV_BUF_CTRL_H264_MODE);

  bk7258_yuv_buf_start();

  ctrl = bk7258_sim_peek32(TEST_YUV_BUF_CTRL);
  CHECK((ctrl & TEST_YUV_BUF_CTRL_YUV_MODE) != 0,
        "expected start() to set yuv_mode, ctrl=0x%x", ctrl);
  CHECK((ctrl & TEST_YUV_BUF_CTRL_H264_MODE) == 0,
        "expected start() to clear h264_mode, ctrl=0x%x", ctrl);
}

static void test_stop_clears_yuv_mode(void)
{
  uint32_t ctrl;

  bk7258_sim_reset();
  bk7258_yuv_buf_start();
  CHECK((bk7258_sim_peek32(TEST_YUV_BUF_CTRL) &
         TEST_YUV_BUF_CTRL_YUV_MODE) != 0, "expected yuv_mode set");

  bk7258_yuv_buf_stop();

  ctrl = bk7258_sim_peek32(TEST_YUV_BUF_CTRL);
  CHECK((ctrl & TEST_YUV_BUF_CTRL_YUV_MODE) == 0,
        "expected stop() to clear yuv_mode, ctrl=0x%x", ctrl);
}

/****************************************************************************
 * init()
 ****************************************************************************/

static void test_init_releases_reset_and_enables_irq(void)
{
  uint32_t global_ctrl;

  bk7258_sim_reset();

  bk7258_yuv_buf_init();

  /* yuv_buf_ll_init(): soft_reset 0 -> 1, then clk_gate_bypass = 1, so
   * the module must be left released from reset with its clock gate
   * bypassed (global_ctrl == 0x3).  Leaving soft_reset at 0 keeps the
   * whole module held in reset, which is what silenced every interrupt
   * source in the field logs. */

  global_ctrl = bk7258_sim_peek32(TEST_YUV_BUF_GLOBAL_CTRL);
  CHECK((global_ctrl & TEST_YUV_BUF_GLOBAL_CTRL_SOFT_RESET) != 0,
        "expected soft_reset=1 (reset released, active-low semantics) "
        "after init(), global_ctrl=0x%x", global_ctrl);
  CHECK((global_ctrl & TEST_YUV_BUF_GLOBAL_CTRL_CLK_GATE_BYPASS) != 0,
        "expected clk_gate_bypass=1 after init(), global_ctrl=0x%x",
        global_ctrl);

  CHECK(bk7258_sim_irq_is_enabled(BK7258_IRQ_YUVB) == true,
        "expected init() to call up_enable_irq(BK7258_IRQ_YUVB)");
}

static void test_init_leaves_interrupts_disabled(void)
{
  bk7258_sim_reset();
  bk7258_yuv_buf_init();

  CHECK(bk7258_sim_peek32(TEST_YUV_BUF_INT_EN) == 0u,
        "expected init() to leave int_en cleared until configure() "
        "selects the events, got 0x%x",
        bk7258_sim_peek32(TEST_YUV_BUF_INT_EN));
}

/****************************************************************************
 * ISR dispatch
 ****************************************************************************/

static int g_frame_cb_count;
static void *g_frame_cb_arg_seen;

static void test_frame_cb(void *arg)
{
  g_frame_cb_count++;
  g_frame_cb_arg_seen = arg;
}

static void test_isr_dispatches_on_yuv_arv(void)
{
  int dummy = 7;
  struct bk7258_yuv_buf_stats_s stats;
  bool fired;

  bk7258_sim_reset();
  bk7258_yuv_buf_init();
  bk7258_yuv_buf_configure(640, 480);
  bk7258_yuv_buf_set_frame_callback(test_frame_cb, &dummy);
  g_frame_cb_count = 0;
  g_frame_cb_arg_seen = NULL;

  bk7258_sim_poke32(TEST_YUV_BUF_INT_STATUS, TEST_INT_YUV_ARV);
  fired = bk7258_sim_irq_fire(BK7258_IRQ_YUVB);

  CHECK(fired == true, "expected an ISR registered for IRQ_YUVB");
  CHECK(g_frame_cb_count == 1,
        "expected the frame callback to fire exactly once on "
        "yuv_arv_int, got %d calls", g_frame_cb_count);
  CHECK(g_frame_cb_arg_seen == &dummy,
        "expected the callback to receive the exact registered arg "
        "pointer");

  bk7258_yuv_buf_get_stats(&stats);
  CHECK(stats.frame_count == 1u,
        "expected frame_count=1, got %u", stats.frame_count);
  CHECK(stats.last_status == TEST_INT_YUV_ARV,
        "expected last_status to record the handled status, got 0x%x",
        stats.last_status);
}

static void test_isr_ignores_line_batch_events(void)
{
  struct bk7258_yuv_buf_stats_s stats;
  int i;

  bk7258_sim_reset();
  bk7258_yuv_buf_init();
  bk7258_yuv_buf_configure(640, 480);
  bk7258_yuv_buf_set_frame_callback(test_frame_cb, NULL);
  g_frame_cb_count = 0;

  /* Even if the hardware were to raise them, the encode-path line-batch
   * events must never be mistaken for a completed frame: a 640x480 frame
   * would otherwise be "completed" 60 times. */

  for (i = 0; i < 60; i++)
    {
      bk7258_sim_poke32(TEST_YUV_BUF_INT_STATUS,
                        (i % 2 == 0) ? TEST_INT_SM0_WR : TEST_INT_SM1_WR);
      (void)bk7258_sim_irq_fire(BK7258_IRQ_YUVB);
    }

  CHECK(g_frame_cb_count == 0,
        "expected no frame callbacks from 60 sm0/sm1 line-batch events, "
        "got %d", g_frame_cb_count);

  bk7258_yuv_buf_get_stats(&stats);
  CHECK(stats.isr_count == 60u,
        "expected all 60 interrupts to be counted, got %u",
        stats.isr_count);
  CHECK(stats.frame_count == 0u,
        "expected frame_count to stay 0, got %u", stats.frame_count);
}

static void test_isr_counts_vsync_and_errors(void)
{
  struct bk7258_yuv_buf_stats_s stats;

  bk7258_sim_reset();
  bk7258_yuv_buf_init();
  bk7258_yuv_buf_configure(640, 480);
  bk7258_yuv_buf_set_frame_callback(test_frame_cb, NULL);
  g_frame_cb_count = 0;

  bk7258_sim_poke32(TEST_YUV_BUF_INT_STATUS, TEST_INT_VSYNC_NEGE);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_YUVB);

  bk7258_sim_poke32(TEST_YUV_BUF_INT_STATUS,
                    TEST_INT_SEN_RESL | TEST_INT_SEN_FULL);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_YUVB);

  bk7258_yuv_buf_get_stats(&stats);

  CHECK(stats.vsync_count == 1u,
        "expected vsync_count=1, got %u", stats.vsync_count);
  CHECK(stats.err_count == 1u,
        "expected err_count=1 (one ISR carrying error bits), got %u",
        stats.err_count);
  CHECK(stats.err_status == (TEST_INT_SEN_RESL | TEST_INT_SEN_FULL),
        "expected err_status to accumulate the error bits seen, got "
        "0x%x", stats.err_status);
  CHECK(g_frame_cb_count == 0,
        "expected no frame callback for vsync/error-only interrupts, "
        "got %d", g_frame_cb_count);
}

static void test_isr_clears_status_via_write_back(void)
{
  uint32_t seeded_status;
  uint32_t status_after;

  bk7258_sim_reset();
  bk7258_yuv_buf_init();
  bk7258_yuv_buf_configure(640, 480);
  bk7258_yuv_buf_set_frame_callback(test_frame_cb, NULL);

  /* The driver's contract (yuv_buf_ll_clear_interrupt_status(): "REG_WRITE
   * (YUV_BUF_R_INT_STATUS, int_status)") is to write back precisely the
   * value it read -- including bits it does not handle, so that an
   * enabled-but-unhandled event cannot latch the level-sensitive
   * interrupt line forever.  This mock models plain memory, not the
   * hardware's write-1-to-clear side effect, so the check is that the
   * exact read value was written back. */

  seeded_status = TEST_INT_YUV_ARV | TEST_INT_ENC_LINE;
  bk7258_sim_poke32(TEST_YUV_BUF_INT_STATUS, seeded_status);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_YUVB);

  status_after = bk7258_sim_peek32(TEST_YUV_BUF_INT_STATUS);
  CHECK(status_after == seeded_status,
        "expected the ISR to acknowledge by writing back exactly the "
        "status it read (0x%x), got 0x%x", seeded_status, status_after);
}

static void test_isr_survives_unregistered_callback(void)
{
  struct bk7258_yuv_buf_stats_s stats;

  bk7258_sim_reset();
  bk7258_yuv_buf_init();
  bk7258_yuv_buf_configure(640, 480);
  bk7258_yuv_buf_set_frame_callback(test_frame_cb, NULL);
  bk7258_yuv_buf_set_frame_callback(NULL, NULL);
  g_frame_cb_count = 0;

  bk7258_sim_poke32(TEST_YUV_BUF_INT_STATUS, TEST_INT_YUV_ARV);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_YUVB);

  bk7258_yuv_buf_get_stats(&stats);
  CHECK(stats.frame_count == 1u,
        "expected the frame to still be counted with no callback "
        "registered, got %u", stats.frame_count);
  CHECK(g_frame_cb_count == 0,
        "expected the unregistered callback not to be invoked, got %d",
        g_frame_cb_count);
}

static void test_start_arms_and_stop_silences_interrupts(void)
{
  bk7258_sim_reset();
  bk7258_yuv_buf_init();
  bk7258_yuv_buf_configure(640, 480);

  bk7258_yuv_buf_start();
  CHECK(bk7258_sim_peek32(TEST_YUV_BUF_INT_EN) ==
        (TEST_INT_VSYNC_NEGE | TEST_INT_YUV_ARV | TEST_INT_SEN_FULL |
         TEST_INT_SEN_RESL | TEST_INT_H264_ERR | TEST_INT_ENC_SLOW),
        "expected start() to arm exactly the frame/error interrupts, "
        "int_en=0x%x", bk7258_sim_peek32(TEST_YUV_BUF_INT_EN));

  bk7258_yuv_buf_stop();
  CHECK(bk7258_sim_peek32(TEST_YUV_BUF_INT_EN) == 0u,
        "expected stop() to disable the interrupts so a still-running "
        "sync detector cannot keep interrupting with nothing to report "
        "to, int_en=0x%x", bk7258_sim_peek32(TEST_YUV_BUF_INT_EN));
}

int main(void)
{
  test_configure_640x480_pixel_register();
  test_configure_other_resolutions();
  test_configure_resize_pixel_register();
  test_configure_ctrl_fields();
  test_configure_clears_h264_mode();
  test_configure_enables_frame_interrupts_only();
  test_configure_writes_error_masks();
  test_configure_clears_stats();
  test_set_frame_buffer_writes_em_and_emr();
  test_set_frame_buffer_rearms_next_buffer();
  test_start_sets_yuv_mode_clears_h264_mode();
  test_stop_clears_yuv_mode();
  test_start_arms_and_stop_silences_interrupts();
  test_init_releases_reset_and_enables_irq();
  test_init_leaves_interrupts_disabled();
  test_isr_dispatches_on_yuv_arv();
  test_isr_ignores_line_batch_events();
  test_isr_counts_vsync_and_errors();
  test_isr_clears_status_via_write_back();
  test_isr_survives_unregistered_callback();

  if (g_failures == 0)
    {
      printf("PASS: all bk7258_yuv_buf.c tests passed\n");
      return 0;
    }

  printf("FAILED: %d assertion(s) failed\n", g_failures);
  return 1;
}
# board/beken/chips/bk7258/sim_tests/Makefile
#
# Desktop simulation test harness for the BK7258 camera driver stack
# (GPIO, software-simulated I2C, minimal DMA, YUV_BUF).  Compiles the
# real production .c files from the parent directory unmodified, with
# register access redirected to mock memory via sim_include/ (see
# sim_include/arm_internal.h for how).  Does not require NuttX, ARM
# toolchain, or hardware -- runs as ordinary native x86 test binaries.
#
# Usage:
#   make            # build and run all tests
#   make clean      # remove build artifacts
#
# SPDX-License-Identifier: Apache-2.0

CC      := gcc
CFLAGS  := -std=c11 -Wall -Wextra -g -O0
CFLAGS  += -I$(CURDIR)/sim_include
CFLAGS  += -I$(CURDIR)
CFLAGS  += -I$(CURDIR)/..
CFLAGS  += -I$(CURDIR)/../include
CFLAGS  += -I$(CURDIR)/../hardware

BUILD_DIR := build

STUBS_SRC := sim_stubs.c

.PHONY: all clean test_gpio test_i2c_sim test_i2c_bitbang test_dma test_yuv_buf test_lcd_spi

all: test_gpio test_i2c_sim test_i2c_bitbang test_dma test_yuv_buf test_lcd_spi

$(BUILD_DIR):
	mkdir -p $(BUILD_DIR)

test_gpio: $(BUILD_DIR)/test_gpio
	@echo "=== Running test_gpio ==="
	@$(BUILD_DIR)/test_gpio

test_i2c_sim: $(BUILD_DIR)/test_i2c_sim
	@echo "=== Running test_i2c_sim ==="
	@$(BUILD_DIR)/test_i2c_sim

test_i2c_bitbang: $(BUILD_DIR)/test_i2c_bitbang
	@echo "=== Running test_i2c_bitbang ==="
	@$(BUILD_DIR)/test_i2c_bitbang

test_dma: $(BUILD_DIR)/test_dma
	@echo "=== Running test_dma ==="
	@$(BUILD_DIR)/test_dma

test_yuv_buf: $(BUILD_DIR)/test_yuv_buf
	@echo "=== Running test_yuv_buf ==="
	@$(BUILD_DIR)/test_yuv_buf

test_lcd_spi: $(BUILD_DIR)/test_lcd_spi
	@echo "=== Running test_lcd_spi ==="
	@$(BUILD_DIR)/test_lcd_spi

$(BUILD_DIR)/test_gpio: test_gpio.c $(STUBS_SRC) ../bk7258_gpio.c | $(BUILD_DIR)
	$(CC) $(CFLAGS) -o $@ $^

$(BUILD_DIR)/test_i2c_sim: test_i2c_sim.c $(STUBS_SRC) ../bk7258_gpio.c ../bk7258_i2c_sim.c | $(BUILD_DIR)
	$(CC) $(CFLAGS) -o $@ $^

$(BUILD_DIR)/test_i2c_bitbang: test_i2c_bitbang.c $(STUBS_SRC) ../bk7258_gpio.c ../bk7258_gc2145_i2c_bitbang.c | $(BUILD_DIR)
	$(CC) $(CFLAGS) -o $@ $^

$(BUILD_DIR)/test_dma: test_dma.c $(STUBS_SRC) ../bk7258_dma.c | $(BUILD_DIR)
	$(CC) $(CFLAGS) -o $@ $^

$(BUILD_DIR)/test_yuv_buf: test_yuv_buf.c $(STUBS_SRC) ../bk7258_yuv_buf.c | $(BUILD_DIR)
	$(CC) $(CFLAGS) -o $@ $^

$(BUILD_DIR)/test_lcd_spi: test_lcd_spi.c $(STUBS_SRC) ../bk7258_gpio.c ../bk7258_ldo33.c ../bk7258_qspi.c | $(BUILD_DIR)
	$(CC) $(CFLAGS) -o $@ $^

clean:
	rm -rf $(BUILD_DIR)
/****************************************************************************
 * board/beken/chips/bk7258/sim_tests/sim_stubs.h
 *
 * Test-facing API for the simulation harness: inspecting/injecting mock
 * register state, and firing registered interrupt handlers directly
 * (since there is no real NVIC in this desktop process).
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef __SIM_TESTS_SIM_STUBS_H
#define __SIM_TESTS_SIM_STUBS_H

#include <stdint.h>
#include <stdbool.h>

/* Reset all mock register memory to zero and clear the recorded IRQ
 * handler table.  Call this at the start of every test case so tests do
 * not leak state into each other. */
void bk7258_sim_reset(void);

/* Direct mock-memory access for test assertions/setup, bypassing the
 * getreg32/putreg32 redirection macros (which take a generic address and
 * are used by the driver code under test; these functions are the same
 * underlying implementation, exposed here under test-facing names so
 * test code reads clearly as "peek/poke the mock register", not "call
 * the macro the driver happens to use"). */
uint32_t bk7258_sim_peek32(uintptr_t addr);
void bk7258_sim_poke32(uintptr_t addr, uint32_t value);

/* Invoke the handler that was registered for `irq` via irq_attach(), as
 * if the (nonexistent, in this test process) NVIC had just delivered
 * that interrupt.  Returns false if no handler was registered for that
 * IRQ number (which a test should generally treat as a failure -- it
 * means the driver never called irq_attach() for the IRQ it was
 * expected to use). */
bool bk7258_sim_irq_fire(int irq);

/* Returns true if up_enable_irq() was called for this IRQ number more
 * recently than any matching up_disable_irq() call (or ever, if
 * up_disable_irq() was never called for it).  Lets tests assert that a
 * driver's init function actually enabled the interrupt it registered,
 * not just attached a handler that would never run. */
bool bk7258_sim_irq_is_enabled(int irq);

/* Total number of up_udelay()/up_mdelay() calls made since the last
 * bk7258_sim_reset(), and the sum of all requested delay microseconds.
 * Lets tests assert "a delay happened" without needing real elapsed
 * wall-clock time (which would make tests slow and flaky). */
unsigned int bk7258_sim_delay_call_count(void);
unsigned long bk7258_sim_delay_total_us(void);

/* Write-observer hook: called synchronously from bk7258_sim_reg_write32()
 * (i.e. from putreg32()/modifyreg32() as used by the driver under test)
 * immediately after the mock memory is updated, with the address and the
 * *new* value.  This lets a test reconstruct the exact sequence of
 * register writes a driver call makes -- e.g. to record every SCL/SDA
 * transition a bit-banged I2C driver performs, in order, to validate
 * protocol timing (bit value driven before the clock's rising edge,
 * held until the falling edge, START/STOP shape, ACK window position)
 * against the actual call sequence rather than only the call's final
 * return value.
 *
 * Only one hook is supported at a time (test harness scope does not
 * need concurrent multi-hook support); passing NULL disables it.
 * bk7258_sim_reset() also clears the hook, so each test must (re)install
 * it after resetting if it needs one. */
typedef void (*bk7258_sim_write_hook_t)(uintptr_t addr, uint32_t value,
                                         void *arg);
void bk7258_sim_set_write_hook(bk7258_sim_write_hook_t hook, void *arg);

/* Read-observer/override hook: called synchronously from
 * bk7258_sim_reg_read32() (i.e. from getreg32() as used by the driver
 * under test) *before* returning the mock memory's stored value.  The
 * hook receives the address and the value currently stored in mock
 * memory, and returns the value that should actually be returned to the
 * caller -- letting a test simulate a real I2C slave actively driving
 * SDA low for an ACK at the exact moment the master samples it, rather
 * than requiring the test to pre-seed a static value before the whole
 * driver call and hope the timing lines up.  If the hook is NULL
 * (default), bk7258_sim_reg_read32() just returns the stored value
 * unchanged. */
typedef uint32_t (*bk7258_sim_read_hook_t)(uintptr_t addr,
                                            uint32_t stored_value,
                                            void *arg);
void bk7258_sim_set_read_hook(bk7258_sim_read_hook_t hook, void *arg);

#endif /* __SIM_TESTS_SIM_STUBS_H */

