/****************************************************************************
 * board/beken/chips/bk7258/sim_tests/sim_include/arm_internal.h
 *
 * Simulation stand-in for NuttX's arm_internal.h.  The real header defines
 * getreg32/putreg32 as macros that directly dereference a raw pointer
 * (*(volatile uint32_t *)(a)) -- that is exactly correct on real hardware
 * but would either segfault (unmapped address) or silently read/write
 * unrelated process memory (mapped address, wrong meaning) if compiled
 * as-is into a desktop test binary.
 *
 * This header redirects getreg32/putreg32 to bk7258_sim_reg_read32() /
 * bk7258_sim_reg_write32(), which operate on a mock register memory
 * space (see sim_stubs.h / sim_stubs.c) covering all the peripheral base
 * addresses used by the drivers under test.  modifyreg32() keeps the
 * same function signature as the real NuttX API and is implemented in
 * sim_stubs.c using the same mock memory.
 *
 * This is the crux of the whole simulation approach: it lets the actual
 * production driver .c files (bk7258_gpio.c, bk7258_dma.c,
 * bk7258_yuv_buf.c, bk7258_i2c_sim.c) be compiled completely unmodified,
 * with every register access transparently redirected to inspectable
 * mock memory, so tests exercise the real bit-manipulation and
 * state-machine logic rather than a hand-rewritten approximation of it.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef __SIM_TESTS_ARM_INTERNAL_H
#define __SIM_TESTS_ARM_INTERNAL_H

#include <stdint.h>

uint32_t bk7258_sim_reg_read32(uintptr_t addr);
void bk7258_sim_reg_write32(uintptr_t addr, uint32_t value);

#define getreg32(a)    bk7258_sim_reg_read32((uintptr_t)(a))
#define putreg32(v, a) bk7258_sim_reg_write32((uintptr_t)(a), (v))

void modifyreg32(unsigned int addr, uint32_t clearbits, uint32_t setbits);

#endif /* __SIM_TESTS_ARM_INTERNAL_H */
/****************************************************************************
 * board/beken/chips/bk7258/sim_tests/sim_stubs.c
 *
 * Simulation harness implementation: mock register memory (a small hash
 * table keyed by address, since the real peripherals are scattered across
 * a sparse address space from 0x44000400 to 0x48020000+ and a flat array
 * covering that whole range would waste ~100MB for no reason), a
 * modifyreg32() implementation matching the real NuttX one's semantics
 * (read-modify-write using the mock memory), and a minimal IRQ table
 * standing in for the real NVIC (irq_attach() records a handler,
 * up_enable_irq()/up_disable_irq() track an enabled-bit per IRQ number,
 * bk7258_sim_irq_fire() is the test-facing "pretend this IRQ fired now").
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include "sim_stubs.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "nuttx/irq.h"
#include "nuttx/arch.h"
#include "nuttx/semaphore.h"
#include "nuttx/clock.h"
#include "arm_internal.h"

#define SIM_REG_TABLE_SIZE  256
#define SIM_IRQ_TABLE_SIZE  128

typedef struct
{
  bool used;
  uintptr_t addr;
  uint32_t value;
} sim_reg_entry_t;

typedef struct
{
  bool attached;
  bool enabled;
  int irq;
  int (*handler)(int irq, void *context, void *arg);
  void *arg;
} sim_irq_entry_t;

static sim_reg_entry_t g_reg_table[SIM_REG_TABLE_SIZE];
static sim_irq_entry_t g_irq_table[SIM_IRQ_TABLE_SIZE];
static unsigned int g_delay_call_count;
static unsigned long g_delay_total_us;
static bk7258_sim_write_hook_t g_write_hook;
static void *g_write_hook_arg;
static bk7258_sim_read_hook_t g_read_hook;
static void *g_read_hook_arg;

void bk7258_sim_set_write_hook(bk7258_sim_write_hook_t hook, void *arg)
{
  g_write_hook = hook;
  g_write_hook_arg = arg;
}

void bk7258_sim_set_read_hook(bk7258_sim_read_hook_t hook, void *arg)
{
  g_read_hook = hook;
  g_read_hook_arg = arg;
}

void bk7258_sim_reset(void)
{
  memset(g_reg_table, 0, sizeof(g_reg_table));
  memset(g_irq_table, 0, sizeof(g_irq_table));
  g_delay_call_count = 0;
  g_delay_total_us = 0;
  g_write_hook = NULL;
  g_write_hook_arg = NULL;
  g_read_hook = NULL;
  g_read_hook_arg = NULL;
}

static sim_reg_entry_t *sim_find_or_create(uintptr_t addr)
{
  unsigned int i;
  int free_slot = -1;

  for (i = 0; i < SIM_REG_TABLE_SIZE; i++)
    {
      if (g_reg_table[i].used && g_reg_table[i].addr == addr)
        {
          return &g_reg_table[i];
        }

      if (!g_reg_table[i].used && free_slot < 0)
        {
          free_slot = (int)i;
        }
    }

  if (free_slot < 0)
    {
      /* Test harness bug (or a driver touching far more distinct
       * addresses than any current driver under test does) -- fail
       * loudly rather than silently corrupting an unrelated slot. */
      fprintf(stderr,
              "bk7258_sim: register table exhausted (addr=0x%lx), "
              "increase SIM_REG_TABLE_SIZE\n", (unsigned long)addr);
      abort();
    }

  g_reg_table[free_slot].used = true;
  g_reg_table[free_slot].addr = addr;
  g_reg_table[free_slot].value = 0;
  return &g_reg_table[free_slot];
}

uint32_t bk7258_sim_reg_read32(uintptr_t addr)
{
  uint32_t stored = sim_find_or_create(addr)->value;

  if (g_read_hook != NULL)
    {
      return g_read_hook(addr, stored, g_read_hook_arg);
    }

  return stored;
}

void bk7258_sim_reg_write32(uintptr_t addr, uint32_t value)
{
  sim_find_or_create(addr)->value = value;

  if (g_write_hook != NULL)
    {
      g_write_hook(addr, value, g_write_hook_arg);
    }
}

uint32_t bk7258_sim_peek32(uintptr_t addr)
{
  return bk7258_sim_reg_read32(addr);
}

void bk7258_sim_poke32(uintptr_t addr, uint32_t value)
{
  bk7258_sim_reg_write32(addr, value);
}

void modifyreg32(unsigned int addr, uint32_t clearbits, uint32_t setbits)
{
  uint32_t value = bk7258_sim_reg_read32((uintptr_t)addr);

  value &= ~clearbits;
  value |= setbits;

  bk7258_sim_reg_write32((uintptr_t)addr, value);
}

irqstate_t enter_critical_section(void)
{
  return 0;
}

void leave_critical_section(irqstate_t flags)
{
  (void)flags;
}

static sim_irq_entry_t *sim_find_irq_slot(int irq, bool create)
{
  unsigned int i;
  int free_slot = -1;

  for (i = 0; i < SIM_IRQ_TABLE_SIZE; i++)
    {
      if (g_irq_table[i].attached && g_irq_table[i].irq == irq)
        {
          return &g_irq_table[i];
        }

      if (!g_irq_table[i].attached && free_slot < 0)
        {
          free_slot = (int)i;
        }
    }

  if (!create)
    {
      return NULL;
    }

  if (free_slot < 0)
    {
      fprintf(stderr,
              "bk7258_sim: irq table exhausted (irq=%d), "
              "increase SIM_IRQ_TABLE_SIZE\n", irq);
      abort();
    }

  g_irq_table[free_slot].irq = irq;
  return &g_irq_table[free_slot];
}

int irq_attach(int irq, xcpt_t isr, void *arg)
{
  sim_irq_entry_t *slot = sim_find_irq_slot(irq, true);

  slot->attached = true;
  slot->handler = isr;
  slot->arg = arg;
  return 0;
}

void up_enable_irq(int irq)
{
  sim_irq_entry_t *slot = sim_find_irq_slot(irq, true);

  slot->enabled = true;
}

void up_disable_irq(int irq)
{
  sim_irq_entry_t *slot = sim_find_irq_slot(irq, false);

  if (slot != NULL)
    {
      slot->enabled = false;
    }
}

bool bk7258_sim_irq_fire(int irq)
{
  sim_irq_entry_t *slot = sim_find_irq_slot(irq, false);

  if (slot == NULL || !slot->attached || slot->handler == NULL)
    {
      return false;
    }

  (void)slot->handler(irq, NULL, slot->arg);
  return true;
}

bool bk7258_sim_irq_is_enabled(int irq)
{
  sim_irq_entry_t *slot = sim_find_irq_slot(irq, false);

  return slot != NULL && slot->enabled;
}

void up_udelay(unsigned long usec)
{
  g_delay_call_count++;
  g_delay_total_us += usec;
}

void up_mdelay(unsigned int msec)
{
  up_udelay((unsigned long)msec * 1000UL);
}

unsigned int bk7258_sim_delay_call_count(void)
{
  return g_delay_call_count;
}

unsigned long bk7258_sim_delay_total_us(void)
{
  return g_delay_total_us;
}

/* Minimal nxsem_*() mock.  This test harness has no real scheduler or
 * concurrency: bk7258_i2c1_write_reg() (the only caller of
 * nxsem_tickwait_uninterruptible() among drivers under test) issues the
 * START condition via a register write, and this harness's write hook
 * (see test_gc2145.c's mock I2C1 slave) synchronously calls
 * bk7258_sim_irq_fire() from *inside* that same write call, all the way
 * through to nxsem_post() -- so by the time write_reg() reaches
 * nxsem_tickwait_uninterruptible(), the semaphore's count is already
 * incremented.  A plain non-blocking counter is therefore sufficient: a
 * real blocking wait is never exercised by this harness (nor could it
 * be, in a single-threaded test process). */
int nxsem_init(sem_t *sem, int pshared, uint32_t value)
{
  (void)pshared;
  sem->count = value;
  return 0;
}

int nxsem_post(sem_t *sem)
{
  sem->count++;
  return 0;
}

int nxsem_tickwait_uninterruptible(sem_t *sem, uint32_t delay)
{
  (void)delay;

  if (sem->count > 0)
    {
      sem->count--;
      return 0;
    }

  /* A real timeout: this harness has no clock to advance, so treat "no
   * count available right now" as an immediate timeout rather than
   * hanging the test process forever. */
  return -1;
}

/* Simulated system tick counter.  Advances by one tick per call so that
 * driver timeout loops written as "read ticks, spin, read ticks again"
 * always observe forward progress and terminate, instead of spinning
 * forever in a test process that has no real timer interrupt. */

clock_t clock_systime_ticks(void)
{
  static clock_t g_sim_ticks;

  return ++g_sim_ticks;
}

