int irq_attach(int irq, xcpt_t isr, void *arg)
{
  sim_irq_entry_t *slot = sim_find_irq_slot(irq, true);

  slot->attached = true;
  slot->handler = isr;
  slot->arg = arg;
  return 0;
}

/* Mirrors NuttX's irq_detach(): the handler is removed, so a subsequent
 * bk7258_sim_irq_fire() for that IRQ returns false.  The enabled flag is
 * kept in the slot (a real irq_detach() does not touch the NVIC enable
 * either), which lets a test distinguish "driver detached its handler"
 * from "driver disabled the interrupt line". */

int irq_detach(int irq)
{
  sim_irq_entry_t *slot = sim_find_irq_slot(irq, false);

  if (slot != NULL)
    {
      slot->handler = NULL;
      slot->arg = NULL;
    }

  return 0;
}

