/****************************************************************************
 * board/beken/chips/bk7258/sim_tests/test_jpeg_enc.c
 *
 * Unit tests for bk7258_jpeg_enc.c, compiled against the real production
 * source (unmodified).  Covers the register-layer contract that the
 * board bring-up depends on: the power/clock enables, the soft-reset
 * end state, the width/8 & height/8 geometry fields, the quantisation
 * table load, the resolution-dependent rate-control byte window, the
 * EOF-only interrupt selection, the EOF handler's byte_count_pfrm read
 * and callback dispatch, and start()/stop() touching only the enable
 * bits they own.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <stdio.h>
#include <string.h>

#include "sim_stubs.h"
#include "bk7258_jpeg_enc.h"
#include "irq.h"

static int g_failures;

#define CHECK(cond, ...) \
  do \
    { \
      if (!(cond)) \
        { \
          g_failures++; \
          printf("FAIL %s:%d: ", __func__, __LINE__); \
          printf(__VA_ARGS__); \
          printf("\n"); \
        } \
    } \
  while (0)

/* Mirrors bk7258_jpeg_enc.c's private register layout as an independent
 * cross-check (see test_dma.c's header comment for the same rationale). */

#define TEST_JPEG_BASE          0x48000000u
#define TEST_JPEG_REG(word_off) (TEST_JPEG_BASE + (word_off) * 4u)

#define TEST_JPEG_DEV_ID          TEST_JPEG_REG(0)
#define TEST_JPEG_GLOBAL_CTRL     TEST_JPEG_REG(2)
#define TEST_GLOBAL_CTRL_SOFT_RESET      (1u << 0)
#define TEST_GLOBAL_CTRL_CLK_GATE_BYPASS (1u << 1)

#define TEST_JPEG_EOF_OFFSET      TEST_JPEG_REG(4)
#define TEST_JPEG_RX_FIFO_DATA    TEST_JPEG_REG(5)
#define TEST_JPEG_INT_STATUS      TEST_JPEG_REG(6)
#define TEST_JPEG_BYTE_COUNT_PFRM TEST_JPEG_REG(7)
#define TEST_JPEG_INT_EN          TEST_JPEG_REG(12)
#define TEST_JPEG_CFG             TEST_JPEG_REG(13)
#define TEST_JPEG_TARGET_BYTE_H   TEST_JPEG_REG(14)
#define TEST_JPEG_TARGET_BYTE_L   TEST_JPEG_REG(15)
#define TEST_JPEG_QUANT_TABLE     TEST_JPEG_REG(0x20)
#define TEST_QUANT_TABLE_LEN      32u

/* int_status event bits (jpeg_ll_is_*_int_triggered()). */

#define TEST_INT_STATUS_SOF        (1u << 0)
#define TEST_INT_STATUS_EOF        (1u << 1)
#define TEST_INT_STATUS_HEAD       (1u << 2)
#define TEST_INT_STATUS_FRAME_ERR  (1u << 3)
#define TEST_INT_STATUS_LINE_CLEAR (1u << 5)

/* int_en bits -- deliberately a different bit order than int_status
 * (jpeg_struct.h REG_0xc): eof is int_en bit[3] but int_status bit[1]. */

#define TEST_INT_EN_FRAME_ERR      (1u << 0)
#define TEST_INT_EN_HEAD           (1u << 1)
#define TEST_INT_EN_SOF            (1u << 2)
#define TEST_INT_EN_EOF            (1u << 3)
#define TEST_INT_EN_LINE_CLEAR     (1u << 7)

#define TEST_CFG_VIDEO_BYTE_REVERSE (1u << 1)
#define TEST_CFG_ENC_EN             (1u << 4)
#define TEST_CFG_X_PIXEL_SHIFT      8u
#define TEST_CFG_ENC_SIZE           (1u << 16)
#define TEST_CFG_BITRATE_CTRL       (1u << 17)
#define TEST_CFG_BITRATE_STEP_SHIFT 18u
#define TEST_CFG_AUTO_STEP          (1u << 20)
#define TEST_CFG_BITRATE_MODE       (1u << 23)
#define TEST_CFG_Y_PIXEL_SHIFT      24u

/* Sysctrl bits the driver must set before the module is usable. */

#define TEST_SYS_REG_0X0C   (0x44010000u + (0x0cu << 2))
#define TEST_SYS_JPEG_CKEN  (1u << 28)
#define TEST_SYS_REG_0X10   (0x44010000u + (0x10u << 2))
#define TEST_SYS_PWD_VIDP   (1u << 7)

/* First and last words of jpeg_ll.c's jpeg_quant_table[], used to prove
 * the table was copied verbatim rather than regenerated. */

#define TEST_QUANT_FIRST_WORD 0x07060608u
#define TEST_QUANT_LAST_WORD  0x32323232u
#define TEST_QUANT_WORD_15    0x3234332eu
#define TEST_QUANT_WORD_16    0x0c090909u

/****************************************************************************
 * init()
 ****************************************************************************/

static void test_init_enables_power_and_clock(void)
{
  bk7258_sim_reset();

  /* Pre-seed pwd_vidp set (the reset/power-down state) so the test shows
   * init() actively clearing it, not merely finding it clear. */

  bk7258_sim_poke32(TEST_SYS_REG_0X10, TEST_SYS_PWD_VIDP);

  CHECK(bk7258_jpeg_enc_init() == 0, "expected init() to return OK");

  CHECK((bk7258_sim_peek32(TEST_SYS_REG_0X10) & TEST_SYS_PWD_VIDP) == 0,
        "expected init() to clear pwd_vidp (sysctrl 0x10 bit[7], "
        "active-high power-down) so the video pipeline is powered, "
        "reg=0x%x", bk7258_sim_peek32(TEST_SYS_REG_0X10));
  CHECK((bk7258_sim_peek32(TEST_SYS_REG_0X0C) & TEST_SYS_JPEG_CKEN) != 0,
        "expected init() to set cpu_device_clk_enable.jpeg_cken "
        "(sysctrl 0x0c bit[28], per sys_hal_set_jpeg_clk_en()), reg=0x%x",
        bk7258_sim_peek32(TEST_SYS_REG_0X0C));
}

static void test_init_soft_reset_end_state(void)
{
  uint32_t global_ctrl;

  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_init();

  /* jpeg_ll_init(): soft_reset = 0 then soft_reset = 1, and nothing
   * else -- so the module ends up released from reset (active-low, same
   * polarity as YUV_BUF's global_ctrl) with clk_gate_bypass STILL 0,
   * i.e. global_ctrl == 0x1 exactly.  clk_gate_bypass belongs to
   * jpeg_ll_enable_jpeg_mode(), which is start()'s job; asserting the
   * exact value here is what catches a well-meaning "make it look like
   * YUV_BUF's 0x3" edit. */

  global_ctrl = bk7258_sim_peek32(TEST_JPEG_GLOBAL_CTRL);
  CHECK(global_ctrl == TEST_GLOBAL_CTRL_SOFT_RESET,
        "expected global_ctrl == 0x1 after init() (soft_reset released, "
        "clk_gate_bypass still 0), got 0x%x", global_ctrl);
}

static void test_init_delays_around_reset(void)
{
  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_init();

  /* The reset must be held long enough to take effect: the driver
   * delays after asserting and after releasing it. */

  CHECK(bk7258_sim_delay_call_count() >= 2,
        "expected at least two delays across the reset assert/release "
        "sequence, got %u", bk7258_sim_delay_call_count());
}

static void test_init_leaves_interrupts_disabled(void)
{
  bk7258_sim_reset();

  /* Stale event bits latched from a previous run must be acknowledged. */

  bk7258_sim_poke32(TEST_JPEG_INT_STATUS,
                    TEST_INT_STATUS_EOF | TEST_INT_STATUS_FRAME_ERR);

  (void)bk7258_jpeg_enc_init();

  CHECK(bk7258_sim_peek32(TEST_JPEG_INT_EN) == 0u,
        "expected init() to leave int_en cleared until configure() "
        "selects the events, got 0x%x",
        bk7258_sim_peek32(TEST_JPEG_INT_EN));
  CHECK(bk7258_sim_peek32(TEST_JPEG_INT_STATUS) ==
        (TEST_INT_STATUS_EOF | TEST_INT_STATUS_FRAME_ERR),
        "expected init() to acknowledge the latched status by writing "
        "back exactly the bits it read (this mock models plain memory, "
        "not the write-1-to-clear side effect), got 0x%x",
        bk7258_sim_peek32(TEST_JPEG_INT_STATUS));
}

static void test_init_attaches_and_enables_irq(void)
