static void test_configure_rejects_bad_geometry(void)
{
  bk7258_sim_reset();

  /* x_pixel/y_pixel are 8-bit fields holding size/8, so a non-multiple
   * of 8 or anything above 2040 cannot be represented -- silently
   * truncating it would encode a different resolution than the caller
   * asked for, which on this hardware means a corrupt bitstream rather
   * than a visibly wrong image. */

  CHECK(bk7258_jpeg_enc_configure(641, 480) != 0,
        "expected configure() to reject a width that is not a multiple "
        "of 8");
  CHECK(bk7258_jpeg_enc_configure(640, 481) != 0,
        "expected configure() to reject a height that is not a multiple "
        "of 8");
  CHECK(bk7258_jpeg_enc_configure(0, 480) != 0,
        "expected configure() to reject a zero width");
  CHECK(bk7258_jpeg_enc_configure(2048, 480) != 0,
        "expected configure() to reject a width above 255*8 = 2040");

  CHECK(bk7258_sim_peek32(TEST_JPEG_CFG) == 0u,
        "expected a rejected configure() to touch no register, cfg=0x%x",
        bk7258_sim_peek32(TEST_JPEG_CFG));
  CHECK(bk7258_sim_peek32(TEST_JPEG_INT_EN) == 0u,
        "expected a rejected configure() to leave int_en alone, "
        "int_en=0x%x", bk7258_sim_peek32(TEST_JPEG_INT_EN));
}

/****************************************************************************
 * configure(): quantisation table
 ****************************************************************************/

static void test_configure_writes_quant_table(void)
{
  uint32_t i;
  uint32_t nonzero = 0;

  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_configure(640, 480);

  /* jpeg_ll_init_quant_table() writes 32 words starting at
   * JPEG_R_QUANT_TABLE (JPEG_R_BASE + 4 * 0x20).  Note jpeg_struct.h
   * declares quat_table[0x1d] (29 words) -- the .c is authoritative,
   * and this test pins the 32-word length so the shorter struct
   * declaration cannot creep back in. */

  for (i = 0; i < TEST_QUANT_TABLE_LEN; i++)
    {
      if (bk7258_sim_peek32(TEST_JPEG_QUANT_TABLE + i * 4u) != 0u)
        {
          nonzero++;
        }
    }

  CHECK(nonzero == TEST_QUANT_TABLE_LEN,
        "expected all %u quant-table words to be written, %u were "
        "non-zero", TEST_QUANT_TABLE_LEN, nonzero);

  CHECK(bk7258_sim_peek32(TEST_JPEG_QUANT_TABLE) == TEST_QUANT_FIRST_WORD,
        "expected quant[0] = 0x%08x (jpeg_ll.c jpeg_quant_table[0]), got "
        "0x%08x", TEST_QUANT_FIRST_WORD,
        bk7258_sim_peek32(TEST_JPEG_QUANT_TABLE));
  CHECK(bk7258_sim_peek32(TEST_JPEG_QUANT_TABLE + 15u * 4u) ==
        TEST_QUANT_WORD_15,
        "expected quant[15] = 0x%08x (last luma word), got 0x%08x",
        TEST_QUANT_WORD_15,
        bk7258_sim_peek32(TEST_JPEG_QUANT_TABLE + 15u * 4u));
  CHECK(bk7258_sim_peek32(TEST_JPEG_QUANT_TABLE + 16u * 4u) ==
        TEST_QUANT_WORD_16,
        "expected quant[16] = 0x%08x (first chroma word), got 0x%08x",
        TEST_QUANT_WORD_16,
        bk7258_sim_peek32(TEST_JPEG_QUANT_TABLE + 16u * 4u));
  CHECK(bk7258_sim_peek32(TEST_JPEG_QUANT_TABLE +
                          (TEST_QUANT_TABLE_LEN - 1u) * 4u) ==
        TEST_QUANT_LAST_WORD,
        "expected quant[31] = 0x%08x, got 0x%08x", TEST_QUANT_LAST_WORD,
        bk7258_sim_peek32(TEST_JPEG_QUANT_TABLE +
                          (TEST_QUANT_TABLE_LEN - 1u) * 4u));
}

/****************************************************************************
 * configure(): rate control
 ****************************************************************************/

static void test_configure_bitrate_window_per_resolution(void)
{
  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_configure(320, 240);
  CHECK(bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_H) == 20u * 1024u &&
        bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_L) == 5u * 1024u,
        "expected the 320-wide window 20K/5K "
        "(JPEG_BITRATE_{MAX,MIN}_SIZE_320_240), got %u/%u",
        bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_H),
        bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_L));

  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_configure(640, 480);
  CHECK(bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_H) == 35u * 1024u &&
        bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_L) == 20u * 1024u,
        "expected the 640-wide window 35K/20K, got %u/%u",
        bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_H),
        bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_L));

  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_configure(1280, 720);
  CHECK(bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_H) == 50u * 1024u &&
        bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_L) == 30u * 1024u,
        "expected the 1280-wide window 50K/30K, got %u/%u",
        bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_H),
        bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_L));

  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_configure(1600, 1200);
  CHECK(bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_H) == 50u * 1024u &&
        bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_L) == 30u * 1024u,
        "expected x_pixel 200 (1600 wide) to share the 1280 window, got "
        "%u/%u", bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_H),
        bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_L));

  /* jpeg_hal_set_target_bitrate()'s switch matches x_pixel exactly
   * against 40/80/160/200 and sends everything else to its default
   * case, which uses JPEG_BITRATE_{MAX,MIN}_SIZE == the 640 window.
   * 864/8 = 108 is such a value; pinning it here documents that this is
   * the vendor's behaviour and not an oversight. */

  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_configure(864, 480);
  CHECK(bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_H) == 35u * 1024u &&
        bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_L) == 20u * 1024u,
        "expected an unlisted width (864) to fall into the vendor's "
        "default 640 window, got %u/%u",
        bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_H),
        bk7258_sim_peek32(TEST_JPEG_TARGET_BYTE_L));
}

