/****************************************************************************
 * Output buffer / FIFO address
 ****************************************************************************/

static void test_set_buffer_records_without_touching_registers(void)
{
  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_configure(640, 480);

  bk7258_jpeg_enc_set_buffer(0x60190000u);

  CHECK(bk7258_jpeg_enc_get_buffer() == 0x60190000u,
        "expected get_buffer() to report the recorded address, got 0x%x",
        bk7258_jpeg_enc_get_buffer());

  /* This module has no destination-address register.  The vendor's
   * jpeg_ll_set_em_base_addr() discards its address argument and ORs
   * 0x20 into eof_offset[16:31], and jpeg_hal_switch_mode() only calls
   * it under "#if (!CONFIG_YUV_BUF)" -- not this board's case.  If a
   * future change starts writing eof_offset, that should be a
   * deliberate, separately justified decision, not a side effect of
   * set_buffer(). */

  CHECK(bk7258_sim_peek32(TEST_JPEG_EOF_OFFSET) == 0u,
        "expected set_buffer() to write no register (in particular not "
        "eof_offset), got eof_offset=0x%x",
        bk7258_sim_peek32(TEST_JPEG_EOF_OFFSET));

  bk7258_jpeg_enc_set_buffer(0x60200000u);
  CHECK(bk7258_jpeg_enc_get_buffer() == 0x60200000u,
        "expected a second set_buffer() to replace the recorded "
        "address, got 0x%x", bk7258_jpeg_enc_get_buffer());
}

