  cfg_after = bk7258_sim_peek32(TEST_JPEG_CFG);
  CHECK(cfg_after == (cfg_before | TEST_CFG_ENC_EN),
        "expected start() to add exactly jpeg_enc_en to cfg (geometry "
        "and rate control must survive): 0x%x -> 0x%x", cfg_before,
        cfg_after);
  CHECK(bk7258_sim_peek32(TEST_JPEG_GLOBAL_CTRL) ==
        (TEST_GLOBAL_CTRL_SOFT_RESET | TEST_GLOBAL_CTRL_CLK_GATE_BYPASS),
        "expected start() to add clk_gate_bypass while leaving "
        "soft_reset released (jpeg_ll_enable_jpeg_mode()), "
        "global_ctrl=0x%x", bk7258_sim_peek32(TEST_JPEG_GLOBAL_CTRL));
  CHECK(bk7258_sim_peek32(TEST_JPEG_INT_EN) == TEST_INT_EN_EOF,
        "expected start() to leave int_en as configure() set it, got "
        "0x%x", bk7258_sim_peek32(TEST_JPEG_INT_EN));
