static void test_stop_touches_only_its_own_bits(void)
{
  uint32_t cfg_running;
  uint32_t cfg_stopped;

  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_init();
  (void)bk7258_jpeg_enc_configure(640, 480);
  bk7258_jpeg_enc_start();
  cfg_running = bk7258_sim_peek32(TEST_JPEG_CFG);

  bk7258_jpeg_enc_stop();

  cfg_stopped = bk7258_sim_peek32(TEST_JPEG_CFG);
  CHECK(cfg_stopped == (cfg_running & ~TEST_CFG_ENC_EN),
        "expected stop() to clear exactly jpeg_enc_en "
        "(jpeg_ll_disable_jpeg_mode()): 0x%x -> 0x%x", cfg_running,
        cfg_stopped);
  CHECK(bk7258_sim_peek32(TEST_JPEG_GLOBAL_CTRL) ==
        TEST_GLOBAL_CTRL_SOFT_RESET,
        "expected stop() to clear clk_gate_bypass but NOT re-assert "
        "soft_reset, global_ctrl=0x%x",
        bk7258_sim_peek32(TEST_JPEG_GLOBAL_CTRL));
  CHECK(bk7258_sim_peek32(TEST_JPEG_INT_EN) == TEST_INT_EN_EOF,
        "expected stop() to leave the interrupt configuration intact so "
        "a later start() can resume without reconfiguring, int_en=0x%x",
        bk7258_sim_peek32(TEST_JPEG_INT_EN));
