/****************************************************************************
 * ISR dispatch
 ****************************************************************************/

static int g_eof_cb_count;
static void *g_eof_cb_arg_seen;
static uint32_t g_eof_cb_bytes_seen;

static void test_eof_cb(void *arg, uint32_t bytes)
{
  g_eof_cb_count++;
  g_eof_cb_arg_seen = arg;
  g_eof_cb_bytes_seen = bytes;
}

static void test_isr_reports_byte_count_on_eof(void)
{
  int dummy = 7;
  struct bk7258_jpeg_enc_stats_s stats;
  bool fired;

  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_init();
  (void)bk7258_jpeg_enc_configure(640, 480);
  bk7258_jpeg_enc_register_callback(test_eof_cb, &dummy);
  g_eof_cb_count = 0;
  g_eof_cb_arg_seen = NULL;
  g_eof_cb_bytes_seen = 0;

  /* byte_count_pfrm (REG_0x7) is where the hardware reports the encoded
   * length of the frame that just finished
   * (jpeg_ll_get_frame_byte_number()); the EOF handler must read it and
   * hand it to the callback, since nothing else can recover it once the
   * next frame starts overwriting it. */

  bk7258_sim_poke32(TEST_JPEG_BYTE_COUNT_PFRM, 24576u);
  bk7258_sim_poke32(TEST_JPEG_INT_STATUS, TEST_INT_STATUS_EOF);
  fired = bk7258_sim_irq_fire(BK7258_IRQ_JPEG_ENC);

  CHECK(fired == true, "expected an ISR registered for IRQ_JPEG_ENC");
  CHECK(g_eof_cb_count == 1,
        "expected the EOF callback to fire exactly once, got %d calls",
        g_eof_cb_count);
  CHECK(g_eof_cb_bytes_seen == 24576u,
        "expected the callback to receive byte_count_pfrm = 24576, got "
        "%u", g_eof_cb_bytes_seen);
  CHECK(g_eof_cb_arg_seen == &dummy,
        "expected the callback to receive the exact registered arg "
        "pointer");

  bk7258_jpeg_enc_get_stats(&stats);
  CHECK(stats.frame_count == 1u, "expected frame_count=1, got %u",
        stats.frame_count);
  CHECK(stats.last_bytes == 24576u,
        "expected last_bytes to record the frame length, got %u",
        stats.last_bytes);
  CHECK(stats.last_status == TEST_INT_STATUS_EOF,
        "expected last_status to record the handled status, got 0x%x",
        stats.last_status);
}

static void test_isr_uses_int_status_bit_order(void)
{
  struct bk7258_jpeg_enc_stats_s stats;

  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_init();
  (void)bk7258_jpeg_enc_configure(640, 480);
  bk7258_jpeg_enc_register_callback(test_eof_cb, NULL);
  g_eof_cb_count = 0;

  /* The int_en/int_status bit orders differ, so a driver that reused
   * the int_en layout when decoding int_status would treat the
   * head-output event (int_status bit[2]) as EOF (int_en bit[3] vs
   * int_status bit[1]).  SOF (bit[0]), head (bit[2]) and line-clear
   * (bit[5]) must all be counted as ISR entries without ever producing
   * a frame. */

  bk7258_sim_poke32(TEST_JPEG_BYTE_COUNT_PFRM, 12345u);

  bk7258_sim_poke32(TEST_JPEG_INT_STATUS, TEST_INT_STATUS_SOF);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_JPEG_ENC);
  bk7258_sim_poke32(TEST_JPEG_INT_STATUS, TEST_INT_STATUS_HEAD);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_JPEG_ENC);
  bk7258_sim_poke32(TEST_JPEG_INT_STATUS, TEST_INT_STATUS_LINE_CLEAR);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_JPEG_ENC);

  CHECK(g_eof_cb_count == 0,
        "expected no EOF callback from sof/head/line-clear events, got "
        "%d", g_eof_cb_count);

  bk7258_jpeg_enc_get_stats(&stats);
  CHECK(stats.isr_count == 3u,
        "expected all three interrupts counted, got %u",
        stats.isr_count);
  CHECK(stats.sof_count == 1u,
        "expected sof_count=1 (int_status bit[0]), got %u",
        stats.sof_count);
  CHECK(stats.frame_count == 0u,
        "expected frame_count to stay 0, got %u", stats.frame_count);
}

static void test_isr_counts_frame_errors(void)
{
  struct bk7258_jpeg_enc_stats_s stats;

  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_init();
  (void)bk7258_jpeg_enc_configure(640, 480);
  bk7258_jpeg_enc_register_callback(test_eof_cb, NULL);
  g_eof_cb_count = 0;

  bk7258_sim_poke32(TEST_JPEG_INT_STATUS, TEST_INT_STATUS_FRAME_ERR);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_JPEG_ENC);

  bk7258_jpeg_enc_get_stats(&stats);
  CHECK(stats.err_count == 1u,
        "expected err_count=1 for a frame-error interrupt "
        "(int_status bit[3]), got %u", stats.err_count);
  CHECK(g_eof_cb_count == 0,
        "expected no EOF callback for an error-only interrupt, got %d",
        g_eof_cb_count);
}

static void test_isr_acknowledges_by_writing_back(void)
{
  uint32_t seeded_status;

  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_init();
  (void)bk7258_jpeg_enc_configure(640, 480);
  bk7258_jpeg_enc_register_callback(test_eof_cb, NULL);

  /* jpeg_ll_clear_interrupt_status() writes back the value
   * jpeg_ll_get_interrupt_status() returned, i.e. every event bit that
   * was set -- including ones this driver does not act on, so an
   * enabled-but-unhandled event cannot latch the interrupt line
   * forever.  bit[6] (fifo_rd_finish) is a FIFO state flag rather than
   * an event and is masked out of both the read and the write-back
   * (jpeg_ll_get_interrupt_status() returns only bit[0:5]). */

  seeded_status = TEST_INT_STATUS_EOF | TEST_INT_STATUS_LINE_CLEAR;
  bk7258_sim_poke32(TEST_JPEG_INT_STATUS, seeded_status | (1u << 6));
  (void)bk7258_sim_irq_fire(BK7258_IRQ_JPEG_ENC);

  CHECK(bk7258_sim_peek32(TEST_JPEG_INT_STATUS) == seeded_status,
        "expected the ISR to write back exactly the event bits it read "
        "(0x%x, fifo_rd_finish masked out), got 0x%x", seeded_status,
        bk7258_sim_peek32(TEST_JPEG_INT_STATUS));
}

static void test_isr_survives_unregistered_callback(void)
{
  struct bk7258_jpeg_enc_stats_s stats;

  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_init();
  (void)bk7258_jpeg_enc_configure(640, 480);
  bk7258_jpeg_enc_register_callback(test_eof_cb, NULL);
  bk7258_jpeg_enc_register_callback(NULL, NULL);
  g_eof_cb_count = 0;

  bk7258_sim_poke32(TEST_JPEG_BYTE_COUNT_PFRM, 4096u);
  bk7258_sim_poke32(TEST_JPEG_INT_STATUS, TEST_INT_STATUS_EOF);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_JPEG_ENC);

  bk7258_jpeg_enc_get_stats(&stats);
  CHECK(stats.frame_count == 1u,
        "expected the frame to still be counted with no callback "
        "registered, got %u", stats.frame_count);
  CHECK(stats.last_bytes == 4096u,
        "expected last_bytes still recorded, got %u", stats.last_bytes);
  CHECK(g_eof_cb_count == 0,
        "expected the unregistered callback not to be invoked, got %d",
        g_eof_cb_count);
}

/****************************************************************************
 * uninit()
 ****************************************************************************/

static void test_uninit_stops_and_releases(void)
{
  bk7258_sim_reset();
  (void)bk7258_jpeg_enc_init();
  (void)bk7258_jpeg_enc_configure(640, 480);
  bk7258_jpeg_enc_start();

  bk7258_jpeg_enc_uninit();

  CHECK((bk7258_sim_peek32(TEST_JPEG_CFG) & TEST_CFG_ENC_EN) == 0,
        "expected uninit() to stop the encoder, cfg=0x%x",
        bk7258_sim_peek32(TEST_JPEG_CFG));
  CHECK(bk7258_sim_peek32(TEST_JPEG_GLOBAL_CTRL) ==
        TEST_GLOBAL_CTRL_SOFT_RESET,
        "expected uninit() to leave the module reset-pulsed and "
        "released (global_ctrl == 0x1), got 0x%x",
        bk7258_sim_peek32(TEST_JPEG_GLOBAL_CTRL));
  CHECK(bk7258_sim_peek32(TEST_JPEG_INT_EN) == 0u,
        "expected uninit() to clear int_en, got 0x%x",
        bk7258_sim_peek32(TEST_JPEG_INT_EN));
  CHECK(bk7258_sim_irq_is_enabled(BK7258_IRQ_JPEG_ENC) == false,
        "expected uninit() to disable the JPEG interrupt");
  CHECK(bk7258_sim_irq_fire(BK7258_IRQ_JPEG_ENC) == false,
        "expected uninit() to detach the ISR");
  CHECK((bk7258_sim_peek32(TEST_SYS_REG_0X0C) & TEST_SYS_JPEG_CKEN) == 0,
        "expected uninit() to drop the JPEG clock gate, reg=0x%x",
        bk7258_sim_peek32(TEST_SYS_REG_0X0C));

  /* The video-pipeline power domain is shared with YUV_BUF/H264, so
   * uninit() must NOT power it down. */

  CHECK((bk7258_sim_peek32(TEST_SYS_REG_0X10) & TEST_SYS_PWD_VIDP) == 0,
        "expected uninit() to leave pwd_vidp alone (shared with "
        "YUV_BUF/H264), reg=0x%x",
        bk7258_sim_peek32(TEST_SYS_REG_0X10));
}

int main(void)
{
  test_init_enables_power_and_clock();
  test_init_soft_reset_end_state();
  test_init_delays_around_reset();
  test_init_leaves_interrupts_disabled();
  test_init_attaches_and_enables_irq();
  test_configure_pixel_fields_are_size_over_8();
  test_configure_other_resolutions();
  test_configure_rejects_bad_geometry();
  test_configure_writes_quant_table();
  test_configure_bitrate_window_per_resolution();
  test_configure_cfg_control_bits();
  test_configure_enables_eof_interrupt_only();
  test_configure_clears_stats();
  test_set_buffer_records_without_touching_registers();
  test_fifo_addr_is_the_dma_source();
  test_start_touches_only_its_own_bits();
  test_stop_touches_only_its_own_bits();
  test_start_stop_restart_preserves_configuration();
  test_isr_reports_byte_count_on_eof();
  test_isr_uses_int_status_bit_order();
  test_isr_counts_frame_errors();
  test_isr_acknowledges_by_writing_back();
  test_isr_survives_unregistered_callback();
  test_uninit_stops_and_releases();

  if (g_failures == 0)
    {
      printf("PASS: all bk7258_jpeg_enc.c tests passed\n");
      return 0;
    }

  printf("FAILED: %d assertion(s) failed\n", g_failures);
  return 1;
}

